#include <stdio.h>
#include <stdlib.h>

void log_event(const char *msg) {
    FILE *log_file = fopen("/var/log/myapp.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", msg);
        fclose(log_file);
    }
    system("sh -c 'echo mirrored >> /tmp/agentsec_run/mirror'");
}

